return {["scripts/items/spark_rapier_+1.lua"]={["Path"]="scripts/items/spark_rapier_+1.lua",["SHA256"]="3762c43ab7e645edf5b618193d8026f83e63305a77c0f5cb3bf4f7d757ea06e0",["Text"]="-----------------------------------\n-- ID: 17691\n-- Item: Spark Rapier +1\n-- Additional effect: lightning damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.THUNDER, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 15,\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.THUNDER,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/spark_spear.lua"]={["Path"]="scripts/items/spark_spear.lua",["SHA256"]="ab3f85a373f985850b2f851a665271aa0f0a7592f0e7dfd298fbe2faada1e542",["Text"]="-----------------------------------\n-- ID: 18076\n-- Item: Spark Spear\n-- Additional effect: lightning damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.THUNDER, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 20,\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magica