artan_bullet_pouch.lua",["SHA256"]="e63766fe9e928364161a0c4c743a5e1094b6ade27b8885cd4ff7bab368f3ddb8",["Text"]="-----------------------------------\n-- ID: 5341\n-- Spartan Bullet Pouch\n-- When used, you will obtain one stack of Spartan Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SPARTAN_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/spartan_hoplon.lua"]={["Path"]="scripts/items/spartan_hoplon.lua",["SHA256"]="e3bedc45e8711c914469f83770435303278fec2c3de448af2b00c350ad2f7f39",["Text"]="-----------------------------------\n-- ID: 15170\n-- Item: Spartan Hoplon\n-- Item Effect: Phalanx\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:addStatusEffect(xi.effect.PHALANX, { power = 10, duration = 180, origin = user }) then -- Retail potency unknown, 10 is a guess. (someone 1000 needles test this thing!)\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.PHALANX)\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/spicy_cracker.lua"]={["Path"]="scripts/items/spicy_cracker.lua",["SHA256"]="0db2aba5f28153ee2c7e7f6fd3fba6f48ce28f3b5e0867f9f9675e69e04f0837",["Text"]="-----------------------------------\n-- ID: 4466\n-- Item: spicy_cracker\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- HP Recovered While Healing 7\n-- Beast Killer +10\n-- Resist Sleep +10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 7)\n    effect:addMod(xi.mod.BEAST_KILLER, 10)\n    effect:addMod(xi.mod.SLEEPRES, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/spirit_lantern.lua"]={["Path"]="scripts/items/spirit_lantern.lua",["SHA256"]="b1fb288b97374d04313881dc2fcda3510c25f45bd4b6a3d5c4be764b3e665a38",["Text"]="-----------------------------------\n-- ID: 18240\n-- Item: Spirit Lantern\n-- Item Effect: Magic Attack +10\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/10080.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.SPIRIT_LANTERN) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SPIRIT_LANTERN)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.SPIRIT_LANTERN })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MATT, 10)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SPIRIT_LANTERN)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/spirit_masque.lua"]={["Path"]="scripts/items/spirit_masque.lua",["SHA256"]="78f496e13bdce5f645d011bb3364d3db48b3485c80386bdae6dfa1c7fd5be4b8",["Text"]="-----------------------------------\n-- ID: 4253\n-- Spirit Masque\n-- A skeletal mask appears on the character's face\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/spirit_maul.lua"]={["Path"]="scripts/items/spirit_maul.lua",["SHA256"]="4adce03df732ec71c97b1551eb11021dae7ee0a29a4c18751adbdc57409cc45e",["Text"]="-----------------------------------\n-- ID: 18853\n-- Item: Spirit Maul\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/spirit_sword.lua"]={["Path"]="scripts/items/spirit_sword.lua",["SHA256"]="b884a416c28dafeeb238fd202f4afb0efe88b023ca3574a1a2384abbf961b293",["Text"]="-----------------------------------\n-- ID: 16613\n-- Item: Spirit Sword\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(4, 6),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/spissatus_cell.lua"]={["Path"]="scripts/items/spissatus_cell.lua",["SHA256"]="8cc9076062cf5ad10523f527c6809dcbdde1b24332cad8054af382d68b3e669d",["Text"]="-----------------------------------\n-- Spissatus Cell\n-- ID 5384\n-- Removes MP Down effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.DEBILITATION, 0x100)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.DEBILITATION, 0x100, 19)\nend\n\nreturn itemObject\n"},["scripts/items/sprig_of_cibol.lua"]={["Path"]="scripts/items/sprig_of_cibol.lua",["SHA256"]="e8cf4229800d4076257236eae0a7b7a4c1f2450d47b9552f07d24fa56761e037",["Text"]="-----------------------------------\n-- ID: 5234\n-- Item: sprig_of_cibol\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sprig_of_hemlock.lua"]={["Path"]="scripts/items/sprig_of_hemlock.lua",["SHA256"]="2ce45c78c5068f2428f68d1372d3387ac9908e1b69c43b830b89b3531014db8a",["Text"]="-----------------------------------\n-- ID: 5985\n-- Item: Sprig of Hemlock\n-- Food Effect: 5 Min, All Races\n-- Paralysis\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.PARALYSIS) then\n        target:addStatusEffect(xi.effect.PARALYSIS, { power = 20, duration = 600, origin = user })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/spriggan_spark.lua"]={["Path"]="scripts/items/spriggan_spark.lua",["SHA256"]="f97ae37a7f1828286d6c2a570a857da631d84188c1a9415f918a5096eb0ca738",["Text"]="-----------------------------------\n-- ID: 6190\n-- Spriggan Spark\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/sprinters_shoes.lua"]={["Path"]="scripts/items/sprinters_shoes.lua",["SHA256"]="a2107540f7b490483bbd714f456b0ca587539277b84541bf8d64f8cd6b255ffa",["Text"]="-----------------------------------\n-- ID: 15754\n-- Item: Sprinter's Shoes\n-- Item Effect: Quickening for 60 minutes\n-- Base speed 10% or +5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.QUICKENING, { power = 5, duration = 3600, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.QUICKENING)\nend\n\nreturn itemObject\n"},["scripts/items/sprout_beret.lua"]={["Path"]="scripts/items/sprout_beret.lua",["SHA256"]="b9cefad1e061e213f8c3e5d705076c80fed47d0f3036ec0eb41e6eca0261880e",["Text"]="-----------------------------------\n-- ID: 15198\n-- Item: Sprout Beret\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +150%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 150\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/steamed_catfish.lua"]={["Path"]="scripts/items/steamed_catfish.lua",["SHA256"]="c85c27f1f359813cddad045860528e39b35a97625ee8fb148ffd2e1f084955da",["Text"]="-----------------------------------\n-- ID: 4557\n-- Item: steamed_catfish\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Health 30\n-- Magic % 1 (cap 110)\n-- Dex 3\n-- Intelligence 1\n-- Mind -3\n-- Earth Res 10\n-- Ranged Accuracy +6% (cap 15)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.FOOD_MPP, 1)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 110)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.EARTH_MEVA, 10)\n    effect:addMod(xi.mod.FOOD_RACCP, 6)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/steamed_crab.lua"]={["Path"]="scripts/items/steamed_crab.lua",["SHA256"]="7e2c72cdeac675b453cbf66e1707d8b400abd773825463f78e8399dad2ae771b",["Text"]="-----------------------------------\n-- ID: 4342\n-- Item: steamed_crab\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Vitality 3\n-- Defense % 27 (cap 65)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FOOD_DEFP, 27)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 65)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/steamed_crayfish.lua"]={["Path"]="scripts/items/steamed_crayfish.lua",["SHA256"]="12f9c7b90e2ec35120fa166bb8299dd7ddf39d197cf6da9ee8e5cbc6335025d1",["Text"]="-----------------------------------\n-- ID: 4338\n-- Item: steamed_crayfish\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Defense % 30\n-- Defense Cap 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_DEFP, 30)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/steel_bullet_pouch.lua"]={["Path"]="scripts/items/steel_bullet_pouch.lua",["SHA256"]="dd5dc32ad5aac44e9f078ccc039e555140c0947f743a04bd0bfaf005a38da352",["Text"]="-----------------------------------\n-- ID: 5416\n-- Steel Bullet Pouch\n-- When used, you will obtain one stack of Steel Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.STEEL_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/stick_of_cotton_candy.lua"]={["Path"]="scripts/items/stick_of_cotton_candy.lua",["SHA256"]="82dc499016dacacc9fb127e39c9433d78b9eeedd13be264a02a406995c5cc4d0",["Text"]="-----------------------------------\n-- ID: 5709\n-- Item: Cotton Candy\n-- Food Effect: 5 Min, All Races\n-----------------------------------\n-- MP % 10 Cap 200\n-- MP Healing 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 10)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 200)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/stick_of_pepperoni.lua"]={["Path"]="scripts/items/stick_of_pepperoni.lua",["SHA256"]="203682662e2432aadeb263f95d3c9425e3371f8d96d2cce9b4bf308b921f7830",["Text"]="-----------------------------------\n-- ID: 5660\n-- Item: stick_of_pepperoni\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP % 3 (assuming 3% from testing, no known cap)\n-- Strength 3\n-- Intelligence -1\n-- Attack % 60 (assuming 60%, cap 30)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 3)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 999)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.INT, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 60)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/stirge_belt.lua"]={["Path"]="scripts/items/stirge_belt.lua",["SHA256"]="0eacb60a441072ef54020a0d5fb0fac951a1dccc104ab2278d2c8d8b36c1acd7",["Text"]="-----------------------------------\n-- ID: 15933\n-- Stirge Belt\n-- Enchantment: 60Min, Costume - Bat\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 256, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/stone_bangles.lua"]={["Path"]="scripts/items/stone_bangles.lua",["SHA256"]="38ce25c7f5dfd0b966d52efd9150b0a5751469e4076673aacd6bc8cf7d9936a4",["Text"]="-----------------------------------\n-- ID: 14988\n-- Stone Bangles\n--  Enchantment: \"Enstone\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local fakeSpell = GetSpell(xi.magic.spell.ENSTONE)\n    xi.spells.enhancing.useEnhancingSpell(target, target, fakeSpell)\nend\n\nreturn itemObject\n"},["scripts/items/stone_quiver.lua"]={["Path"]="scripts/items/stone_quiver.lua",["SHA256"]="b567d45d696fab0296bd4d2871c9f8565793e3557b2b27bf37dcffd3efc29ada",["Text"]="-----------------------------------\n-- ID: 4219\n-- Stone Quiver\n-- When used, you will obtain one stack of Stone Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.STONE_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/stoneskin_torque.lua"]={["Path"]="scripts/items/stoneskin_torque.lua",["SHA256"]="6be133fd9ae4d176ab34be5ea13136b7c727d078a7ce467466c3174b5069e16c",["Text"]="-----------------------------------\n-- ID: 13170\n-- Item: Stoneskin Torque\n-- Item Effect: Stoneskin\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.STONESKIN_TORQUE) then\n        if target:addStatusEffect(xi.effect.STONESKIN, { power = 104, duration = 300, origin = user, tier = 4, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.STONESKIN_TORQUE }) then\n            target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.STONESKIN)\n        else\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        end\n    end\nend\n\nreturn itemObject\n"},["scripts/items/storm_axe.lua"]={["Path"]="scripts/items/storm_axe.lua",["SHA256"]="9c3bce5642c207d30116b6ad794de83a944c99f523b77021825f673659c5e4d8",["Text"]="-----------------------------------\n-- ID: 16675\n-- Item: Storm Axe\n-- Additional effect: wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 5 + utils.clamp(dStat * 10 / 54, 0, 10), -- 0-10% over 54 int\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/stratus_cell.lua"]={["Path"]="scripts/items/stratus_cell.lua",["SHA256"]="2d085ec97ae30fae431bdf25e479276df6c86d04e62236f775d255297ef4901d",["Text"]="-----------------------------------\n-- Stratus Cell\n-- ID 5369\n-- Unlocks leg and feet equipment\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.ENCUMBRANCE_I, 0x0180)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.ENCUMBRANCE_I, 0x0180, 4)\nend\n\nreturn itemObject\n"},["scripts/items/strength_potion.lua"]={["Path"]="scripts/items/strength_potion.lua",["SHA256"]="381c081f4bad21805c71e85cce50dd840f0335c303e634ad8656c7073a6dbb4b",["Text"]="-----------------------------------\n--  ID: 4199\n--  Item: Strength Potion\n--  Strength 7\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.STR_BOOST, { power = 7, duration = 180, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/strip_of_bison_jerky.lua"]={["Path"]="scripts/items/strip_of_bison_jerky.lua",["SHA256"]="4d49660f7c4070ae1d4c7eab11ceaa41eac2ee16b82d0bb77fc946ad3e6abfda",["Text"]="-----------------------------------\n-- ID: 5207\n-- Item: strip_of_bison_jerky\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Strength 5\n-- Mind -2\n-- Attack % 18\n-- Attack Cap 70\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 5)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 70)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/strip_of_buffalo_jerky.lua"]={["Path"]="scripts/items/strip_of_buffalo_jerky.lua",["SHA256"]="5492bc6f65c746135a114997a64393bf87b96e7ad27d356483a555ac61c2870b",["Text"]="-----------------------------------\n-- ID: 5196\n-- Item: strip_of_buffalo_jerky\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength 4\n-- Mind -2\n-- Attack % 18\n-- Attack Cap 65\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 4)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 65)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/strip_of_meat_jerky.lua"]={["Path"]="scripts/items/strip_of_meat_jerky.lua",["SHA256"]="818b8ac7746bc958d62a316ac8b11959659c5653b1483710688be7918ef9d659",["Text"]="-----------------------------------\n-- ID: 4376\n-- Item: strip_of_meat_jerky\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength 3\n-- Intelligence -1\n-- Attack % 23\n-- Attack Cap 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.INT, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 23)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/strip_of_sheep_jerky.lua"]={["Path"]="scripts/items/strip_of_sheep_jerky.lua",["SHA256"]="77a80a030590cd0e0b161ced5a1db1a6479b7de90d873c7e317ac4da4a9f5ad2",["Text"]="-----------------------------------\n-- ID: 4518\n-- Item: strip_of_sheep_jerky\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Strength 3\n-- Intelligence -1\n-- Attack % 23\n-- Attack Cap 35\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.INT, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 23)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 35)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/strip_of_smoked_mackerel.lua"]={["Path"]="scripts/items/strip_of_smoked_mackerel.lua",["SHA256"]="48db023ea3c3da594cfa9478780b1cc6a61e096a6c21dd2530bb4b0c11b0448d",["Text"]="-----------------------------------\n-- ID: 5943\n-- Item: Strip of Smoked Mackerel\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Agility 4\n-- Vitality -3\n-- Evasion +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.VIT, -3)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/stuffed_pitaru.lua"]={["Path"]="scripts/items/stuffed_pitaru.lua",["SHA256"]="12f3c172e2d83cf7a7f8bfc95ac7c675fcd9030420b4a367597b038b74490cab",["Text"]="-----------------------------------\n-- ID: 5889\n-- Item: stuffed_pitaru\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- MP +6% (cap 100)\n-- Increases rate of magic skill gains by 20%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 6)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 100)\n    effect:addMod(xi.mod.MAGIC_SKILLUP_RATE, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sturdy_slacks.lua"]={["Path"]="scripts/items/sturdy_slacks.lua",["SHA256"]="1881935e3ca7ea42107fc724ed2f76371a145311cf6c79c0c887356b3ff792d3",["Text"]="-----------------------------------\n-- ID: 15611\n-- Item: sturdy_slacks\n-- Item Effect: HP +7, MP +7\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.STURDY_SLACKS) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.STURDY_SLACKS)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.STURDY_SLACKS) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.STURDY_SLACKS })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HP, 7)\n    effect:addMod(xi.mod.MP, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sturdy_trousers.lua"]={["Path"]="scripts/items/sturdy_trousers.lua",["SHA256"]="f4667132a099fdf9d17ff13bbd016211d3aff97496dda45471e60a1518264bd2",["Text"]="-----------------------------------\n-- ID: 15610\n-- Item: sturdy_trousers\n-- Item Effect: HP +10\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.MAX_HP_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.STURDY_TROUSERS) ~= nil then\n        target:delStatusEffect(xi.effect.MAX_HP_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.STURDY_TROUSERS)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.STURDY_TROUSERS) then\n        target:addStatusEffect(xi.effect.MAX_HP_BOOST, { power = 10, duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.STURDY_TROUSERS })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/sugar_rusk.lua"]={["Path"]="scripts/items/sugar_rusk.lua",["SHA256"]="f7e2d2cecc44f66d09315939198306d7c218808e57118566a878315f813644be",["Text"]="-----------------------------------\n-- ID: 5782\n-- Item: sugar_rusk\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- High-quality success rate +1\n-- Synthesis failure rate -2%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.SYNTH_HQ_RATE, 1)\n    effect:addMod(xi.mod.SYNTH_MATERIAL_LOSS, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sultans_belt.lua"]={["Path"]="scripts/items/sultans_belt.lua",["SHA256"]="f0583b42fa3810bbcf3a19d94dbe187c771bce1456f1d7fde57f9648cf9b5d83",["Text"]="-----------------------------------\n-- ID: 15867\n-- Item: sultans_belt\n-- Item Effect: STR +10\n-- Duration: 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.STR_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SULTANS_BELT) ~= nil then\n        target:delStatusEffect(xi.effect.STR_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SULTANS_BELT)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.SULTANS_BELT) then\n        target:addStatusEffect(xi.effect.STR_BOOST, { power = 10, duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.SULTANS_BELT })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/summer_fan.lua"]={["Path"]="scripts/items/summer_fan.lua",["SHA256"]="25571b0965bc4b50d36de1adc6856ba28a3c328d219208d502b434d558c7bbf6",["Text"]="-----------------------------------\n-- ID: 4252\n-- Summer Fan\n-- A paper fan appears in the user's right hand\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/summoner_die.lua"]={["Path"]="scripts/items/summoner_die.lua",["SHA256"]="cdfcfa8994c19f303d507d684838639878ce588f4652fb3ab04d676965ef72db",["Text"]="-----------------------------------\n-- ID: 5191\n-- Summoner Die\n-- Teaches the job ability Evoker's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.EVOKERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.EVOKERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/super_ether.lua"]={["Path"]="scripts/items/super_ether.lua",["SHA256"]="78186197edd699025e545f1e2249a8316f455eed21df32323759a656c8c4c726",["Text"]="-----------------------------------\n-- ID: 4136\n-- Item: Super Ether\n-- Item Effect: Restores 100 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(100 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/super_ether_+1.lua"]={["Path"]="scripts/items/super_ether_+1.lua",["SHA256"]="0d67bd8ba35f55a091b21a1a56a0feecb3d8115030a455265efad453436ba656",["Text"]="-----------------------------------\n-- ID: 4137\n-- Item: Super Ether +1\n-- Item Effect: Restores 105 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(105 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/super_ether_+2.lua"]={["Path"]="scripts/items/super_ether_+2.lua",["SHA256"]="a68ddf003ec2af5e0b52e6b8f6e4faab339a3db01fc11983ef9ba39c24fa3ca3",["Text"]="-----------------------------------\n-- ID: 4138\n-- Item: Super Ether +2\n-- Item Effect: Restores 110 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(110 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/super_ether_+3.lua"]={["Path"]="scripts/items/super_ether_+3.lua",["SHA256"]="859053fa01443db1f265791b97c8ed146f912b701f53a8c51461153e9310f8ce",["Text"]="-----------------------------------\n-- ID: 4139\n-- Item: Super Ether +3\n-- Item Effect: Restores 120 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(120 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/super_reraiser.lua"]={["Path"]="scripts/items/super_reraiser.lua",["SHA256"]="a93d453db90dce1bd4beb401fa595943fd3abfcd50eb97b29c4620ef3900d071",["Text"]="-----------------------------------\n-- ID: 5770\n-- Item: Super Reraiser\n-- Item Effect: This potion functions the same way as the spell Reraise.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 3600\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 3, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/super_reraiser_tank.lua"]={["Path"]="scripts/items/super_reraiser_tank.lua",["SHA256"]="36328a885c287f434fe117f7cacdab1afa9dbca2e7e983c66871aa11db959780",["Text"]="-----------------------------------\n-- ID: 26272\n-- Super Reraiser Tank\n-- When used, you will obtain one super reraiser\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SUPER_RERAISER, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/suppa_shuriken_pouch.lua"]={["Path"]="scripts/items/suppa_shuriken_pouch.lua",["SHA256"]="79a02bb65bc0d5fd1573191dc1acb34cf828b0244b884b077316a8e181717405",["Text"]="-----------------------------------\n-- ID: 6309\n-- Item: Sup. Sh. Pouch\n-- When used, you will obtain one stack of Suppa Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SUPPA_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/suzakus_scythe.lua"]={["Path"]="scripts/items/suzakus_scythe.lua",["SHA256"]="91b2c5e7d07ab143cf1c0d2cb0f06205d0255a81ca047fd4046444b13504d243",["Text"]="-----------------------------------\n-- ID: 18043\n-- Item: Suzaku's Scythe\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 2, -- TODO: this has negative scaling, as in if you have low dINT it procs more. This is capped dINT.\n        basePower      = math.randomInt(22, 30),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/sweet_baked_apple.lua"]={["Path"]="scripts/items/sweet_baked_apple.lua",["SHA256"]="8d98914d687dc13749751dcd670397a46b7fc329dba2fda5b2a4dc7cb39b5b93",["Text"]="-----------------------------------\n-- ID: 4336\n-- Item: sweet_baked_apple\n-- Food Effect: 1hour, All Races\n-----------------------------------\n-- Magic Points 25\n-- Intelligence 4\n-- MP Recovered While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 25)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sweet_rice_cake.lua"]={["Path"]="scripts/items/sweet_rice_cake.lua",["SHA256"]="c740effcf7734585d192b19de25993e4e4c4ab79c1a524fa4788237c9596075c",["Text"]="-----------------------------------\n-- ID: 4270\n-- Item: sweet_rice_cake\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- MP 17\n-- Vitality 2\n-- Intelligence 3\n-- Mind 1\n-- HP Recovered While Healing 2\n-- MP Recovered While Healing 2\n-- Evasion 5\n-- Resist Silence 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 17)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 2)\n    effect:addMod(xi.mod.EVA, 5)\n    effect:addMod(xi.mod.SILENCERES, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/tactical_ring.lua"]={["Path"]="scripts/items/tactical_ring.lua",["SHA256"]="f652e50b4b6e86a952a5e5bbc7ab87d9e558bcc75b01ec23a6fc569a2c110ec9",["Text"]="-----------------------------------\n-- ID: 14679\n-- Item: Tactical Ring\n-- Item Effect: Regain 20\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/2205.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.TACTICAL_RING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TACTICAL_RING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.TACTICAL_RING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.REGAIN, 20)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TACTICAL_RING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/tacticians_die.lua"]={["Path"]="scripts/items/tacticians_die.lua",["SHA256"]="3a7e76dd6e30887a6d3966d6831d84822bff98a0ca9344c34e8cc22f2ff6b8d0",["Text"]="-----------------------------------\n-- ID: 5501\n-- Tactician's Die\n-- Teaches the job ability Tactician's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.TACTICIANS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.TACTICIANS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/taikyoku_kenpogi.lua"]={["Path"]="scripts/items/taikyoku_kenpogi.lua",["SHA256"]="26e0727f487bcfee09949154fe74f4ac38c00497c7ec96a5a8e6a20c3d0da644",["Text"]="-----------------------------------\n-- ID: 14541\n-- Item: taikyoku_kenpogi\n-- Item Effect: Eva +3\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.EVASION_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TAIKYOKU_KENPOGI) ~= nil then\n        target:delStatusEffect(xi.effect.EVASION_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TAIKYOKU_KENPOGI)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.TAIKYOKU_KENPOGI) then\n        target:addStatusEffect(xi.effect.EVASION_BOOST, { power = 3, duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.TAIKYOKU_KENPOGI })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/talaria.lua"]={["Path"]="scripts/items/talaria.lua",["SHA256"]="2972946b5e87972b76b7c0b07370a836a22455fc5380cc436580f4ca26351cdf",["Text"]="-----------------------------------\n-- ID: 11403\n-- Item: Talaria\n-- Enchantment: Increases movement speed.\n-- Durration: 60 Mins\n-- Base speed 10% or +5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.ENCHANTMENT) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 3600, origin = user, subType = 11403 })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MOVE_SPEED_QUICKENING, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/talisman_obi.lua"]={["Path"]="scripts/items/talisman_obi.lua",["SHA256"]="a9f68ad183006679c124677f0487fbfdf236766b8a635a0e1891e6492524556f",["Text"]="-----------------------------------\n-- ID: 15462\n-- Item: Talisman Obi\n-- Effect: 3Min, MP+12 Enmity-2\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TALISMAN_OBI) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TALISMAN_OBI)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.TALISMAN_OBI) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.TALISMAN_OBI })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MP, 12)\n    effect:addMod(xi.mod.ENMITY, -2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/tamas_ring.lua"]={["Path"]="scripts/items/tamas_ring.lua",["SHA256"]="b203c6033e2db718b61d3f21ea19fe70c47b25cf1f20111b2d4e0fe6c0708acb",["Text"]="-----------------------------------\n-- ID: 15545\n-- Tamas Ring\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\nend\n\nitemObject.onItemUse = function(target)\nend\n\nitemObject.onItemDrop = function(target, item, recycleBin)\n    if not recycleBin then\n        xi.mission.setVar(target, xi.mission.log_id.COP, xi.mission.id.cop.DAWN, 'Timer', 1, GetSystemTime() + 27 * 24 * 60 * 60)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/tanners_belt.lua"]={["Path"]="scripts/items/tanners_belt.lua",["SHA256"]="de8c9c2224c3d8b20e8fdd85dd60b30195c0ee21b40f9dd5dd5bb970dbdd9ae2",["Text"]="-----------------------------------\n-- ID: 15448\n-- Item: Tanners belt\n-- Enchantment: Synthesis image support\n-- Duration: 8Min\n-- Leathercraft Skill +3\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.LEATHERCRAFT_IMAGERY) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.LEATHERCRAFT_IMAGERY, { power = 3, duration = 480, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/tarutaru_rice_cake.lua"]={["Path"]="scripts/items/tarutaru_rice_cake.lua",["SHA256"]="795b1716076da21dcf3287bbb57c596bf90316c78ddb1ecd7e74be1dd87c6543",["Text"]="-----------------------------------\n-- ID: 5296\n-- Tarutaru Rice Cake\n-- Enchantment: 60Min, Costume - Tarutaru child (female)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 823, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/tarutaru_snare.lua"]={["Path"]="scripts/items/tarutaru_snare.lua",["SHA256"]="8a757efc6fff1e10537e139b70be87b14bdd915e380e4cb8984fc33400ed5363",["Text"]="-----------------------------------\n-- ID: 5329\n-- Item: Tarutaru snare\n-- Used in Pirates Chart quest\n-- When used on one of the quest nms, lowers its damage for 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.piratesChart.onItemCheck(target, item, caster)\nend\n\nitemObject.onItemUse = function(target)\n    target:setMobMod(xi.mobMod.BASE_DAMAGE_MULTIPLIER, 1)\n    target:setLocalVar('snareTimeLimit', GetSystemTime() + 60)\nend\n\nreturn itemObject\n"},["scripts/items/tathlum_belt.lua"]={["Path"]="scripts/items/tathlum_belt.lua",["SHA256"]="0ff20a6799eea7849f18be4ad46135c278745d84d6218c8fc4395809e27c7743",["Text"]="-----------------------------------\n-- ID: 15296\n-- tathlum_belt\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.TATHLUM, 8 } })\nend\n\nreturn itemObject\n"},["scripts/items/tavnazian_goby.lua"]={["Path"]="scripts/items/tavnazian_goby.lua",["SHA256"]="d7d31e71437b699ea2bb57529598912c130798bd752a14d2ba909d6136d79955",["Text"]="-----------------------------------\n-- ID: 5130\n-- Item: Tavnazian Goby\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 4\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/tavnazian_ring.lua"]={["Path"]="scripts/items/tavnazian_ring.lua",["SHA256"]="74d47fd1553c0fcfe121cf08d25db29f412e172af203f9c7e2a573fb956a99a5",["Text"]="-----------------------------------\n-- ID: 14672\n-- Tavnazian Ring\n-- Enchantment: \"Teleport-Tavnazia\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:setPos(0, -23.5, 29.15, 63, 26)\nend\n\nreturn itemObject\n"}};
